Describe 'Rename-DistroNexusInstance lifecycle facade' -Tag 'Unit', 'Public', 'Lifecycle' {
    BeforeAll { Import-Module (Join-Path $PSScriptRoot '..\..\..\..\src\PowerShell\DistroNexus.psd1') -Force }
    It 'uses a token-only execute route and does not migrate tags in the facade' { InModuleScope DistroNexus { Mock Invoke-DistroNexusWorkspaceBridge { if ($Operation -like '*.preview.v1') { [pscustomobject]@{ PreviewToken=('d'*64) } } else { [pscustomobject]@{ Succeeded=$true } } }; Mock Rename-DistroNexusInstanceTags {}; Rename-DistroNexusInstance -Name Old -NewName New -Confirm:$false | Out-Null; Should -Invoke Invoke-DistroNexusWorkspaceBridge -ParameterFilter { $Operation -eq 'instance.rename.preview.v1' -and $Payload.NewName -eq 'New' } -Times 1; Should -Invoke Invoke-DistroNexusWorkspaceBridge -ParameterFilter { $Operation -eq 'instance.rename.execute.v1' -and $Payload.Keys.Count -eq 1 } -Times 1; Should -Invoke Rename-DistroNexusInstanceTags -Times 0 } }
}
